import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { Helmet } from 'react-helmet-async';

// TrackShipment page
// Purpose: simple, realistic tracking UI with a placeholder result card.
const TrackShipment = () => {
  const [trackingId, setTrackingId] = useState('');
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);

  const exampleId = 'VT-12345678';

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!trackingId) return;
    setLoading(true);

    // Simulate an API call and return static dummy data
    setTimeout(() => {
      setResult({
        id: trackingId,
        status: 'In Transit',
        location: 'Vadodara, Gujarat',
        eta: '2025-11-18'
      });
      setLoading(false);
    }, 700);
  };

  const clear = () => {
    setTrackingId('');
    setResult(null);
  };

  return (
    <>
      <Helmet>
        <title>Track Shipment | Venus Transport</title>
        <meta name="description" content="Track your Venus Transport shipment using your tracking ID and get real-time status updates." />
      </Helmet>

      {/* Hero / Breadcrumb */}
      <section className="hero-section bg-gradient py-5" style={{background: 'linear-gradient(90deg,#0f172a,#111827)'}} data-aos="fade-down">
        <div className="container">
          <div className="row align-items-center">
            <div className="col-md-8 text-white">
              <h1 className="display-6 fw-bold">Track Your Shipment</h1>
              <p className="mb-0 lead">Enter your tracking ID to know your delivery status</p>
            </div>
            <div className="col-md-4 text-md-end mt-3 mt-md-0">
              <nav aria-label="breadcrumb">
                <ol className="breadcrumb justify-content-md-end mb-0 bg-transparent">
                  <li className="breadcrumb-item"><Link to="/">Home</Link></li>
                  <li className="breadcrumb-item active text-white" aria-current="page">Track</li>
                </ol>
              </nav>
            </div>
          </div>
        </div>
      </section>

      <section className="py-5">
        <div className="container">
          <div className="row gy-4">
            <div className="col-lg-6" data-aos="fade-up">
              <div className="card shadow-sm h-100">
                <div className="card-body">
                  <h5 className="card-title">Track by ID</h5>
                  <p className="text-muted">Enter the tracking ID received at booking. Example: <code>{exampleId}</code></p>

                  <form onSubmit={handleSubmit} className="row g-2 align-items-center">
                    <div className="col-12">
                      <label htmlFor="trackingId" className="form-label visually-hidden">Tracking ID</label>
                      <input
                        id="trackingId"
                        className="form-control form-control-lg"
                        placeholder="Enter tracking ID (e.g. VT-12345678)"
                        value={trackingId}
                        onChange={(e) => setTrackingId(e.target.value)}
                        required
                      />
                    </div>

                    <div className="col-auto">
                      <button type="submit" className="btn btn-primary btn-lg">
                        {loading ? 'Checking...' : 'Track Now'}
                      </button>
                    </div>

                    <div className="col-auto">
                      <button type="button" className="btn btn-outline-secondary btn-lg" onClick={() => setTrackingId(exampleId)}>
                        Use Example
                      </button>
                    </div>
                  </form>

                  <hr />
                  <p className="mb-0">Need help? <a href="https://wa.me/919313879878" target="_blank" rel="noreferrer">Chat on WhatsApp</a> or <Link to="/contact">contact us</Link>.</p>
                </div>
              </div>
            </div>

            <div className="col-lg-6" data-aos="fade-up" data-aos-delay="100">
              <div className="card shadow-sm h-100">
                <div className="card-body">
                  <h5 className="card-title">Shipment Status</h5>

                  {!result && (
                    <div className="alert alert-secondary">No tracking result yet. Enter an ID and click <strong>Track Now</strong>.</div>
                  )}

                  {result && (
                    <div className="mt-3">
                      <div className="mb-3">
                        <strong>Tracking ID:</strong> {result.id}
                      </div>

                      <div className="mb-2">
                        <span className="badge bg-warning text-dark">{result.status}</span>
                      </div>

                      <ul className="list-unstyled mt-3">
                        <li><strong>Current Location:</strong> {result.location}</li>
                        <li><strong>Estimated Delivery:</strong> {result.eta}</li>
                      </ul>

                      <div className="mt-3 d-flex gap-2">
                        <button className="btn btn-outline-primary" onClick={() => window.print()}>Print</button>
                        <button className="btn btn-secondary" onClick={clear}>Clear</button>
                      </div>
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      </section>
    </>
  );
};

export default TrackShipment;
